    m = re.search(r"-?\d+(?:\.\d+)?", s)
    return float(m.group()) if m else None

def naver_financials(code: str, period: str = "annual") -> pd.DataFrame:
    j = requests.get(f"https://m.stock.naver.com/api/stock/{code}/finance/{period}",
                     headers=H, timeout=TIMEOUT).json()["financeInfo"]
