def daum_quote(code: str) -> dict:
    """Daum quote snapshot. regularTradePrice = KRX official (regular-session) close of `date`;
    tradePrice = integrated KRX+NXT last; basePrice = previous official close. Referer mandatory."""
    r = requests.get(f"https://finance.daum.net/api/quotes/A{code}",
                     params={"summary": "false", "changeStatistics": "true"},
                     headers={**H, "Referer": f"https://finance.daum.net/quotes/A{code}"}, timeout=TIMEOUT)
    r.raise_for_status()
    return r.json()

